const D = { pixel:.45, energy:.5, hue:150, speed:1, density:.5, dither:.4, scale:1, x:.5, y:.5, style:'gameboy', act:'quantize', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/360; s/=100; b/=100; const i=Math.floor(h*6), f=h*6-i; const p=b*(1-s), q=b*(1-f*s), tt=b*(1-(1-f)*s); let r,g,bl; switch(((i%6)+6)%6){case 0:r=b;g=tt;bl=p;break;case 1:r=q;g=b;bl=p;break;case 2:r=p;g=b;bl=tt;break;case 3:r=p;g=q;bl=b;break;case 4:r=tt;g=p;bl=b;break;default:r=b;g=p;bl=q;} return [r*255,g*255,bl*255]; };

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const act=P.act;

// ---- palettes as HSB triples ----
const PALS={
  gameboy:[[120,60,18],[110,58,38],[80,55,62],[74,52,86]],
  ink:[[220,6,6],[220,6,26],[220,5,50],[220,4,74],[220,3,94]],
  sepia:[[28,55,10],[30,58,32],[33,52,56],[36,40,78],[40,22,95]],
  ega:[[0,0,4],[240,80,70],[120,80,60],[180,75,72],[0,80,72],[300,70,72],[36,90,74],[0,0,96]],
  cmyk:[[0,0,6],[190,85,88],[320,80,86],[55,90,92],[0,0,98]],
  thermal:[[260,80,10],[270,85,40],[330,90,70],[10,95,92],[45,95,98],[52,30,100]]
};
const base=PALS[style]||PALS.gameboy;

// hue-rotated, seed-jittered, RGB-cached palette (keyed on style+hue+seed)
const pkey=style+':'+Math.round(P.hue)+':'+P.seed;
if(!S.pal || S.pkey!==pkey){
  S.pkey=pkey; const dh=(P.hue-150)*0.55; S.pal=[];
  for(let i=0;i<base.length;i++){
    const e=base[i]; const jb=clp(e[2]+(fr(i*3+1)-0.5)*8,2,100);
    S.pal.push(hsb2rgb(e[0]+dh, e[1], jb));
  }
}
const pal=S.pal, np=pal.length;

// ---- downsample buffer (coarser as pixel->1) ----
const qw=Math.max(8,Math.round(lrp(168,26,clp(P.pixel,0,1))));
const qh=Math.max(6,Math.round(qw*Hh/W));
if(!S.q || S.qkey!==qw+'x'+qh){ if(S.q){try{S.q.remove();}catch(e){}} S.qkey=qw+'x'+qh; S.q=createGraphics(qw,qh); S.q.colorMode(HSB,360,100,100,100); }
const q=S.q;
q.clear();
try{ q.drawingContext.drawImage(drawingContext.canvas,0,0,W,Hh,0,0,qw,qh); }catch(e){}

// ---- quantize with moving plasma + ordered dither ----
const bayer=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5];
const amp=lrp(18,120,clp(P.energy,0,1))*(0.6+0.4*K.intensity);
const spd=Math.max(0.05,P.speed);
const t=K.t*spd;
const freq=lrp(1.5,5,clp(P.density,0,1));
const dith=clp(P.dither,0,1)*40;
const secTint=(act==='drift')?K.section*22:0;
q.loadPixels();
const px=q.pixels;
for(let yy=0;yy<qh;yy++){
  const fy=yy/qh;
  for(let xx=0;xx<qw;xx++){
    const fx=xx/qw;
    const o=4*(yy*qw+xx);
    let r=px[o], g=px[o+1], b=px[o+2];
    // moving plasma (self-motion on flat input)
    const pl=(Math.sin((fx*freq*3.1)+t*1.7)+Math.sin((fy*freq*2.7)-t*1.2)+Math.sin(((fx+fy)*freq*2.3)+t*2.1+secTint*0.02))/3;
    let add=pl*amp + A.bass*30*Math.sin(fy*6+t);
    // ordered dither
    add += ((bayer[(yy&3)*4+(xx&3)]/16)-0.5)*dith;
    r=clp(r+add,0,255); g=clp(g+add,0,255); b=clp(b+add,0,255);
    // nearest palette entry
    let bi=0,bd=1e9;
    for(let k=0;k<np;k++){ const c=pal[k]; const dr=r-c[0],dg=g-c[1],db=b-c[2]; const dd=dr*dr+dg*dg+db*db; if(dd<bd){bd=dd;bi=k;} }
    const c=pal[bi]; px[o]=c[0]; px[o+1]=c[1]; px[o+2]=c[2]; px[o+3]=255;
  }
}
q.updatePixels();

// ---- draw back, nearest-neighbour chunky ----
drawingContext.imageSmoothingEnabled=false;
image(q,0,0,W,Hh);
drawingContext.imageSmoothingEnabled=true;

// scanline texture for 'ega'/'cmyk' print feel (subtle, static grid is fine; motion carried by plasma)
if(style==='cmyk'){ blendMode(MULTIPLY); stroke(0,0,0,10); strokeWeight(1); for(let yy=0;yy<Hh;yy+=Math.max(3,Math.round(u*0.006))) line(0,yy,W,yy); noStroke(); blendMode(BLEND); }
blendMode(BLEND); noTint(); drawingContext.imageSmoothingEnabled=true;
